// The game's sounds (games/asteroids/assets/sounds/, generated by tools/gen_sounds.py),
// and voices to play them: a few per sound, taken in turn, so a quick second shot
// doesn't cut off the first; the thrust's own, looping, played while the ship thrusts.
import * as wgf from "./wgf.js";

function voices(name, count, volume) {
    const sound = wgf.wgf_sound_create(`sounds/${name}.ogg`);
    const pool = [];
    for (let i = 0; i < count; i++) {
        const voice = wgf.wgf_voice_create(sound);
        wgf.wgf_voice_set_volume(voice, volume);
        pool.push(voice);
    }
    wgf.wgf_resource_release(sound); // each voice holds its own
    return { voices: pool, next: 0 };
}

export class Sounds {
    constructor() {
        this.fire = voices("fire", 4, 0.5);
        this.bangLarge = voices("bang_large", 3, 0.8);
        this.bangMedium = voices("bang_medium", 3, 0.7);
        this.bangSmall = voices("bang_small", 3, 0.6);
        this.extraLife = voices("extra_life", 1, 0.7);
        this.start = voices("start", 1, 0.6);
        this.gameOver = voices("game_over", 1, 0.7);
        const thrust = wgf.wgf_sound_create("sounds/thrust.ogg");
        this.thrustVoice = wgf.wgf_voice_create(thrust);
        wgf.wgf_voice_set_loop(this.thrustVoice, true);
        wgf.wgf_voice_set_volume(this.thrustVoice, 0.45);
        wgf.wgf_resource_release(thrust);
    }

    play(pool) {
        const voice = pool.voices[pool.next];
        pool.next = (pool.next + 1) % pool.voices.length;
        wgf.wgf_voice_stop(voice);
        wgf.wgf_voice_play(voice);
    }

    thrust(on) {
        if (on) wgf.wgf_voice_play(this.thrustVoice);
        else wgf.wgf_voice_stop(this.thrustVoice);
    }
}
